python3 << 'EOF'
import json

files = [
    '/root/controller_params.json',
    '/root/control_log.json',
    '/root/metrics.json'
]

print("JSON Format Validation:\n")
for fpath in files:
    try:
        with open(fpath, 'r') as f:
            data = json.load(f)
        print(f"✓ {fpath.split('/')[-1]:25} Valid JSON")

        # Validate specific fields
        if 'controller_params' in fpath:
            required = ['horizon_N', 'Q_diag', 'R_diag', 'K_lqr', 'A_matrix', 'B_matrix']
            missing = [k for k in required if k not in data]
            if not missing:
                print(f"  └─ All required fields present ✓")
            else:
                print(f"  └─ Missing fields: {missing} ✗")

        elif 'control_log' in fpath:
            if 'phase' in data and 'data' in data and len(data['data']) > 0:
                first_entry = data['data'][0]
                required = ['time', 'tensions', 'velocities', 'control_inputs', 'references']
                missing = [k for k in required if k not in first_entry]
                if not missing:
                    print(f"  └─ {len(data['data'])} log entries with all required fields ✓")
                else:
                    print(f"  └─ Missing fields: {missing} ✗")
            else:
                print(f"  └─ Invalid log structure ✗")

        elif 'metrics' in fpath:
            required = ['steady_state_error', 'settling_time', 'max_tension', 'min_tension']
            missing = [k for k in required if k not in data]
            if not missing:
                print(f"  └─ All required metrics present ✓")
            else:
                print(f"  └─ Missing metrics: {missing} ✗")

    except json.JSONDecodeError as e:
        print(f"✗ {fpath.split('/')[-1]:25} Invalid JSON: {e}")
    except Exception as e:
        print(f"✗ {fpath.split('/')[-1]:25} Error: {e}")

print("\nValidation complete!")
EOF
